    }
    search(target) {
        let curr = this.head;
        for (let i = this.maxLevel - 1; i >= 0; i--) {
            while (curr.forward[i] && curr.forward[i].val < target) {
                curr = curr.forward[i];
            }
        }
        curr = curr.forward[0];
        return Boolean(curr && curr.val === target);
